<script setup>
import {ref,onMounted,computed} from 'vue';import {api} from '../store';
const datos=ref([]),error=ref(''),buscar=ref(''),form=ref({estudiante:'',email:'',curso:'',nota:0,asistencia:100});
const visibles=computed(()=>datos.value.filter(x=>(x.estudiante+' '+x.curso).toLowerCase().includes(buscar.value.toLowerCase())));
async function cargar(){try{datos.value=await api('/registros')}catch(e){error.value=e.message}}
function limpiar(){form.value={estudiante:'',email:'',curso:'',nota:0,asistencia:100}}
async function guardar(){try{error.value='';const x=form.value;await api('/registros'+(x.id?'/'+x.id:''),x.id?'PUT':'POST',x);limpiar();await cargar()}catch(e){error.value=e.message}}
async function borrar(x){if(!confirm('¿Eliminar registro?'))return;try{await api('/registros/'+x.id,'DELETE');await cargar()}catch(e){error.value=e.message}}
onMounted(cargar);
</script><template><div class="page-heading"><div><div class="eyebrow">GESTIÓN DOCENTE</div><h2>Estudiantes y calificaciones</h2><p>Registra los resultados de cada estudiante y curso.</p></div><RouterLink to="/analisis?origen=registros" class="btn btn-primary">Analizar registros</RouterLink></div><div v-if="error" class="alert alert-danger">{{error}}</div><form class="card p-4 mb-4" @submit.prevent="guardar"><h5>{{form.id?'Editar registro':'Nuevo registro académico'}}</h5><div class="row g-3"><label class="col-md-4">Estudiante<input class="form-control" v-model.trim="form.estudiante" required></label><label class="col-md-4">Correo de cuenta (opcional)<input class="form-control" type="email" v-model.trim="form.email"></label><label class="col-md-4">Curso<input class="form-control" v-model.trim="form.curso" required></label><label class="col-md-6">Nota (0–20)<input class="form-control" type="number" min="0" max="20" step="0.01" v-model.number="form.nota" required></label><label class="col-md-6">Asistencia (%)<input class="form-control" type="number" min="0" max="100" step="0.01" v-model.number="form.asistencia" required></label></div><small class="text-secondary mt-2">Para la demostración local, el correo vincula la nota a una cuenta estudiantil. Usa únicamente datos ficticios.</small><div class="mt-3"><button class="btn btn-primary me-2">Guardar</button><button type="button" class="btn btn-outline-secondary" @click="limpiar">Cancelar</button></div></form><div class="card p-4"><div class="panel-heading"><h5>Registros ({{datos.length}})</h5><input class="form-control w-auto" placeholder="Buscar estudiante o curso" v-model="buscar"></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Estudiante</th><th>Curso</th><th>Nota</th><th>Asistencia</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in visibles" :key="x.id"><td>{{x.estudiante}}<div class="small text-secondary">{{x.email}}</div></td><td>{{x.curso}}</td><td>{{x.nota}}</td><td>{{x.asistencia}}%</td><td><button class="btn btn-sm btn-outline-primary me-2" @click="form={...x}">Editar</button><button class="btn btn-sm btn-outline-danger" @click="borrar(x)">Eliminar</button></td></tr></tbody></table></div><p v-if="!visibles.length" class="empty-state">Sin registros.</p></div></template>